local config = {
  ui_story_32110401_1_dialog_content = "I have some good news to tell you.",
  ui_story_32110401_2_dialog_content = "I've been following a special training regimen to improve the accuracy of my attacks.",
  ui_story_32110401_3_dialog_content = "And now I'm finally starting to see some results!",
  ui_story_32110401_4_dialog_content = "You know, even the incredible Miss Vice praised me for how far I've come!",
  ui_story_32110401_5_dialog_content = "<anim type=Shake>B-B-Bullseye, Z-Zarya... Look... Y-You did it...</anim>",
  ui_story_32110401_6_dialog_content = "<anim type=Shake>C-C-Clearly this means... p-p-precision... isn't a p-p-problem for you... anymore...</anim>",
  ui_story_32110401_7_dialog_content = "Really? It didn't really feel like I actually hit the target...",
  ui_story_32110401_8_dialog_content = "Anyway, I suppose that means I've achieved my special training goal. Thank you so much!",
  ui_story_32110401_9_dialog_content = "<anim type=Shake>Great... Hopefully, this means there'll be a lot less furniture on the Colossus that needs to be unfrozen... for some strange reason...</anim>",
  ui_story_32110401_10_dialog_content = "<size=50><anim type=Shake>Achoo!</anim></size>",
  ui_story_32110401_11_dialog_content = "\"The incredible Miss Vice...\"",
  ui_story_32110401_12_dialog_content = "Zarya, you seem to put every reliable big sister type you meet on a pedestal...",
  ui_story_32110401_13_dialog_content = "There's no one else around here right now.",
  ui_story_32110401_14_dialog_content = "Would you like to take this opportunity to see the results of my training with Miss Vice?",
  ui_story_32110401_15_dialog_content = "Sure.",
  ui_story_32110401_16_dialog_content = "I just had a hot cup of joe and I'm ready to go! If you think you can freeze me, bring it on!",
  ui_story_32110401_17_dialog_content = "Uh... You don't seem to believe that I've improved at all.",
  ui_story_32110401_18_dialog_content = "Considering how hard Miss Vice has been working to train me, I simply HAVE to impress you!",
  ui_story_32110401_19_dialog_content = "<color=#e8d9bb>One minute later...</color>",
  ui_story_32110401_20_dialog_content = "First... focus my mind.",
  ui_story_32110401_21_dialog_content = "Then... gather the Lumina and control the power, just like wiggling my pinky.",
  ui_story_32110401_22_dialog_content = "Finally... seize the right moment! Pour the power into a single stream and unleash it!",
  ui_story_32110401_23_dialog_content = "My lounge! You're gonna turn it into an ice cave!",
  ui_story_32110401_24_dialog_content = "Huh?",
  ui_story_32110401_25_dialog_content = "I was aiming specifically at the ribbon tied to that chair...",
  ui_story_32110401_26_dialog_content = "Why's the whole room freezing over?!",
  ui_story_32110401_27_dialog_content = "Maybe you're just not feeling one hundred percent right now. How about we try again another day...?",
  ui_story_32110401_28_dialog_content = "No! Miss Vice says that perfect control is achieved through rigorous practice! I won't make any excuses for myself!",
  ui_story_32110401_29_dialog_content = "That was simply an accident just now. Let's try again somewhere else!",
  ui_story_32110401_30_dialog_content = "I'll use that coffee can as my target this time! I'll definitely hit it!",
  ui_story_32110401_31_dialog_content = "Wait a minute—",
  ui_story_32110401_32_dialog_content = "<size=45>Not that one! That's no ordinary coffee!</size>",
  ui_story_32110401_33_dialog_content = "Hyaa!",
  ui_story_32110401_34_dialog_content = "<size=45>Aaaaaah—!</size>",
  ui_story_32110401_35_dialog_content = "Those are the super-expensive coffee beans I asked Ms. Sheol to get for me!",
  ui_story_32110401_36_dialog_content = "I-I haven't even had a chance to try them yet... and now they're all... frozen...",
  ui_story_32110401_37_dialog_content = "Ah... S-Sorry!",
  ui_story_32110401_38_dialog_content = "Sigh... All that effort, all the hard work I've put in these past few days... it was all for nothing.",
  ui_story_32110401_39_option_content = "(Give Zarya a specific suggestion)",
  ui_story_32110401_40_dialog_content = "I have a suggestion.",
  ui_story_32110401_41_dialog_content = "Before working on your accuracy, try reducing the intensity of the Lumina you're releasing.",
  ui_story_32110401_42_dialog_content = "That'll definitely make it easier to control.",
  ui_story_32110401_43_option_content = "(Tell Zarya to drink more hot water)",
  ui_story_32110401_44_dialog_content = "Forget about all that for now, just drink more hot water and warm up a bit first.",
  ui_story_32110401_45_dialog_content = "I don't want to... You drink some...",
  ui_story_32110401_46_dialog_content = "Don't let it get you down. Let's put precise targeting to one side for now.",
  ui_story_32110401_47_dialog_content = "Maybe if you start off by reducing the power of your Lumina, your casting might turn out smoother?",
  ui_story_32110401_48_dialog_content = "Huh?",
  ui_story_32110401_49_dialog_content = "I can't make any promises. I'm not even an Aurorian, after all.",
  ui_story_32110401_50_dialog_content = "I'm just thinking, based on my ability as a Caelestite, it feels like you're exerting too much power.",
  ui_story_32110401_51_dialog_content = "It makes sense that you might be able to control your power better if you try launching less of it at once.",
  ui_story_32110401_52_dialog_content = "Once you master this first step, you can gradually increase your power until you can fully control it.",
  ui_story_32110401_53_dialog_content = "That certainly is a viable solution.",
  ui_story_32110401_54_dialog_content = "But that alone might be too simple for you.",
  ui_story_32110401_55_dialog_content = "Hmm?",
  ui_story_32110401_56_dialog_content = "I wonder if there are any cheap bottles or cans around here...",
  ui_story_32110401_57_dialog_content = "Ah, found one. This should do the trick.",
  ui_story_32110401_58_dialog_content = "Why are you putting that bottle on your head?",
  ui_story_32110401_59_dialog_content = "You don't mean...?!",
  ui_story_32110401_60_dialog_content = "Zarya, I want you to hit the bottle on my head with your ice.",
  ui_story_32110401_61_dialog_content = "Huh? That sounds incredibly dangerous!",
  ui_story_32110401_62_dialog_content = "If I were to hit you by mistake, you'd...!",
  ui_story_32110401_63_dialog_content = "Why do you assume you'll fail even before giving it a try?",
  ui_story_32110401_64_dialog_content = "Don't worry. It's not like I haven't been hit by your Luminatics before. I must've built up a little resistance to them by now.",
  ui_story_32110401_65_dialog_content = "But...",
  ui_story_32110401_66_dialog_content = "Relax, Vice and I have done this before.",
  ui_story_32110401_67_dialog_content = "If you're really that worried, just use the minimum amount of power you can muster to hit the bottle.",
  ui_story_32110401_68_dialog_content = "I get the feeling you find it difficult to control your power, right? Well, maybe it's because you're always practicing with inanimate objects.",
  ui_story_32110401_69_dialog_content = "Also, you make a point of practicing your skills in places with no one around.",
  ui_story_32110401_70_dialog_content = "So, even if you mess up, you don't have to worry about hurting anyone.",
  ui_story_32110401_71_dialog_content = "Right... but what's wrong with that?",
  ui_story_32110401_72_dialog_content = "Haven't you ever considered that, because you're always training in empty areas, against lifeless targets...",
  ui_story_32110401_73_dialog_content = "You've basically never had to focus your power before.",
  ui_story_32110401_74_dialog_content = "!!!",
  ui_story_32110401_75_dialog_content = "This time, you have to hit the bottle on my head...",
  ui_story_32110401_76_dialog_content = "If you don't want me to get hurt, that is.",
  ui_story_32110401_77_dialog_content = "PlayerName... that actually makes a lot of sense.",
  ui_story_32110401_78_dialog_content = "I can't turn back now!",
  ui_story_32110401_79_dialog_content = "(I can't make any mistakes this time... I can't afford to mess up...)",
  ui_story_32110401_80_dialog_content = "(Just like Miss Vice said, block out all unnecessary thoughts...)",
  ui_story_32110401_81_dialog_content = "(Only by merging your consciousness with the ice crystals can you succeed...)",
  ui_story_32110401_82_dialog_content = "And remember—use the minimum amount of power...",
  ui_story_32110401_83_dialog_content = "Let's give the snow some color!",
  ui_story_32110401_84_dialog_content = "I did it?!",
  ui_story_32110401_85_dialog_content = "Phew... That's what I thought.",
  ui_story_32110401_86_dialog_content = "Zarya, it's not that you're not good with accuracy—you're just too good at blasting out your power.",
  ui_story_32110401_87_dialog_content = "What does that mean?",
  ui_story_32110401_88_dialog_content = "It means you shouldn't worry about doing your utmost to control your accuracy like everyone else does...",
  ui_story_32110401_89_dialog_content = "But you do need to reduce your power.",
  ui_story_32110401_90_dialog_content = "It's just like pouring coffee—it's naturally easier to pour out too much coffee when your can has a wide opening.",
  ui_story_32110401_91_dialog_content = "... My power... has a wide opening?",
  ui_story_32110401_92_dialog_content = "That's right. So I advise you to use faster and more flexible combat methods when you're in battle.",
  ui_story_32110401_93_dialog_content = "This should considerably reduce your chances of making a mistake.",
  ui_story_32110401_94_dialog_content = "Hmm... Got it! Next time, I'll keep this in mind and try doing the same again!",
  ui_story_32110401_95_dialog_content = "Wow, and you didn't even give me any backchat... It looks like your skill is not the only thing that's grown today—your personality seems to have leveled up too...",
  ui_story_32110401_96_dialog_content = "What are you saying, PlayerName?",
  ui_story_32110401_97_dialog_content = "You mean... I've grown in another way, besides improving my Luminatics?",
  ui_story_32110401_98_dialog_content = "Erm, yes... What's up?",
  ui_story_32110401_99_dialog_content = "So you think I'm more or less a mature lady now, is that so?",
  ui_story_32110401_100_dialog_content = "Huh? Why would you say that...? I don't think so, no...",
  ui_story_32110401_101_dialog_content = "Yikes! What are you planning to do?!",
  ui_story_32110401_102_dialog_content = "... My dear PlayerName...",
  ui_story_32110401_103_dialog_content = "Would you please continue to be my training partner from now on?",
  ui_story_32110401_104_dialog_content = "After all, when I have you for a target dummy, that's when my mind's most focused...",
  ui_story_32110401_105_dialog_content = "Pleeeeease!",
  ui_story_32110401_106_dialog_content = "... I need to think about it!",
  ui_story_32110601_1_dialog_content = "(When I was a child, I was often left home alone.)",
  ui_story_32110601_2_dialog_content = "(My sister had to go out on patrol and couldn't be with me all the time. The other children wouldn't play with me either.)",
  ui_story_32110601_3_dialog_content = "(There were only a few things in life that could bring a smile to my face back then, and most of them lay within the storybook my sister gave me.)",
  ui_story_32110601_4_dialog_content = "(The book spoke of the ice of Northland—of how it grew solid and strong, but became warm seawater when exposed to the outside world.)",
  ui_story_32110601_5_dialog_content = "(My sister also used to tell me that we could put on our swimsuits and visit that fascinating land of mystery one day.)",
  ui_story_32110601_6_dialog_content = "(But...)",
  ui_story_32110601_7_dialog_content = "<color=#e8d9bb>Splashing—</color>",
  ui_story_32110601_8_dialog_content = "Zarya?",
  ui_story_32110601_9_dialog_content = "<size=45>Zarya?</size>",
  ui_story_32110601_10_dialog_content = "Oh...",
  ui_story_32110601_11_dialog_content = "What's up? Is this the wrong place?",
  ui_story_32110601_12_dialog_content = "Isn't this the ocean from that book?",
  ui_story_32110601_13_dialog_content = "That's not what's wrong, PlayerName.",
  ui_story_32110601_14_dialog_content = "It's just that... this is the first time I've seen an ocean without solid ice with my eyes. It's... astonishing.",
  ui_story_32110601_15_dialog_content = "It's so beautiful...",
  ui_story_32110601_16_dialog_content = "The outside world is huge... This is just a little part of it.",
  ui_story_32110601_17_dialog_content = "Try putting your feet in the water. There's nothing quite like it.",
  ui_story_32110601_18_dialog_content = "Oh? Like this?",
  ui_story_32110601_19_dialog_content = "Oh—",
  ui_story_32110601_20_dialog_content = "What do you think? Feels good, right?",
  ui_story_32110601_21_dialog_content = "It's not quite the same as the hot springs of Northland, but it's still very nice... It's so very warm.",
  ui_story_32110601_22_dialog_content = "I used to bathe in the hot springs back in Northland...",
  ui_story_32110601_23_dialog_content = "The winds in Northland are so cold and biting. My sister would refuse to leave the cozy hot spring.",
  ui_story_32110601_24_dialog_content = "But it's different here. The wind's so gentle.",
  ui_story_32110601_25_dialog_content = "Even if I were to swim beneath the ocean breeze, I wouldn't feel that piercing cold.",
  ui_story_32110601_26_dialog_content = "If only she...",
  ui_story_32110601_27_dialog_content = "<color=#e8d9bb>Pitter-patter—</color>",
  ui_story_32110601_28_dialog_content = "Huh? It just started raining all of a sudden!",
  ui_story_32110601_29_dialog_content = "Even after I borrowed all these sunny dolls from Hiiro and the others...",
  ui_story_32110601_30_dialog_content = "Wasn't fifty of them enough?!",
  ui_story_32110601_31_dialog_content = "Maybe... we should call it quits for today?",
  ui_story_32110601_32_dialog_content = "What are you looking at?",
  ui_story_32110601_33_dialog_content = "This rain...",
  ui_story_32110601_34_dialog_content = "The rainwater here... It's so light and it won't freeze...",
  ui_story_32110601_35_dialog_content = "You'll catch a cold if you carry on like this.",
  ui_story_32110601_36_dialog_content = "And the new clothes you're wearing today are gonna get all wet.",
  ui_story_32110601_37_dialog_content = "I won't get sick from warm rain like this.",
  ui_story_32110601_38_dialog_content = "Compared to the freezing coffin I was imprisoned in for a hundred years, this rain is like nature's gentle caress.",
  ui_story_32110601_39_dialog_content = "This is what I imagine it would feel like to have the fairies from my storybook fluttering their wings over my face.",
  ui_story_32110601_40_dialog_content = "Hey, and now you just sit down?",
  ui_story_32110601_41_dialog_content = "What a handful...",
  ui_story_32110601_42_dialog_content = "<color=#e8d9bb>The rain pitter-patters down...</color>",
  ui_story_32110601_43_dialog_content = "<color=#e8d9bb>Zarya sits on the rocks, her clothes wet with the cold rain.</color>",
  ui_story_32110601_44_dialog_content = "Hmm?",
  ui_story_32110601_45_dialog_content = "Phew, it's a good thing I brought an umbrella...",
  ui_story_32110601_46_dialog_content = "PlayerName, you really don't need to worry about me.",
  ui_story_32110601_47_dialog_content = "I'm not worried! It's just...",
  ui_story_32110601_48_dialog_content = "... Uh, if you catch a cold, No. 33 will blame me for not taking care of you!",
  ui_story_32110601_49_dialog_content = "Pfft—",
  ui_story_32110601_50_dialog_content = "So that's it, eh? It's really not honest of you...",
  ui_story_32110601_51_dialog_content = "Just move it! Don't think for a second that I'm anywhere near as reckless as you...",
  ui_story_32110601_52_dialog_content = "I just get the feeling something's weighing on your mind.",
  ui_story_32110601_53_dialog_content = "You've been feeling a little weird since you saw the ocean.",
  ui_story_32110601_54_dialog_content = "Would you like to tell me what's bothering you?",
  ui_story_32110601_55_dialog_content = "As you know, the weather in Northland is harsh to say the least.",
  ui_story_32110601_56_dialog_content = "When I was growing up, gloomy weather like this was a sign that hail would soon be upon us.",
  ui_story_32110601_57_dialog_content = "My sister would hurry back home to avoid the hail, and even my father would put a temporary pause on his business affairs.",
  ui_story_32110601_58_dialog_content = "That was all so long ago, but still, I remember the terrifying sound of the falling hail.",
  ui_story_32110601_59_dialog_content = "Whenever I was afraid, my sister would take out a storybook and comfort me with tales of the outside world.",
  ui_story_32110601_60_dialog_content = "She would caress my head and whisper softly in my ear:",
  ui_story_32110601_61_dialog_content = "\"Zarya, you know there's no need to be afraid of the rain and snow, right? There's an amazing world waiting for you out there.\"",
  ui_story_32110601_62_dialog_content = "\"There are places where the sea remains unfrozen, and the rain is soft and soothing.\"",
  ui_story_32110601_63_dialog_content = "\"If we get the chance, let's wear our swimsuits and swim in a beautiful exotic paradise someday.\"",
  ui_story_32110601_64_dialog_content = "And now...",
  ui_story_32110601_65_dialog_content = "Here I am.",
  ui_story_32110601_66_dialog_content = "Where the sea never freezes... wearing my swimsuit...",
  ui_story_32110601_67_dialog_content = "But there's no one here to celebrate this dream coming to fruition with me.",
  ui_story_32110601_68_dialog_content = "Was everyone in your family as interested in the outside world as you are?",
  ui_story_32110601_69_dialog_content = "I think... they were.",
  ui_story_32110601_70_dialog_content = "My sister, of course, always wanted to show me the outside world, but her work always got in the way.",
  ui_story_32110601_71_dialog_content = "My dad was also intrigued with foreign products.",
  ui_story_32110601_72_dialog_content = "As for my mom... she died when I was young, so I can barely even remember her now.",
  ui_story_32110601_73_dialog_content = "But she always clung to my father, who traveled often and far afield, so I assume she'd probably be curious about the wider world.",
  ui_story_32110601_74_dialog_content = "So, haven't you already made good on your agreement with them all?",
  ui_story_32110601_75_dialog_content = "Hmm?",
  ui_story_32110601_76_dialog_content = "After you left Northland, instead of holing yourself up in your room, you chose to walk around outside.",
  ui_story_32110601_77_dialog_content = "You went out to see the world that filled them with such curiosity and wanderlust.",
  ui_story_32110601_78_dialog_content = "Cherish the present and the sky will always be clear.",
  ui_story_32110601_79_dialog_content = "Heh, is that your silver tongue at work again...? You really do have the gift of the gab.",
  ui_story_32110601_80_dialog_content = "Unfortunately, it doesn't look like the weather will clear up today, regardless of how glib you might be.",
  ui_story_32110601_81_dialog_content = "<color=#e8d9bb>A gentle breeze blows, gradually causing the restless clouds to dissipate as quickly as they formed.</color>",
  ui_story_32110601_82_dialog_content = "<color=#e8d9bb>Shafts of sunlight pierce the oppressive clouds and beam down onto the beach.</color>",
  ui_story_32110601_83_dialog_content = "Aha! It's like the rain really does just start and stop whenever you tell it to...",
  ui_story_32110601_84_dialog_content = "Hmm, I guess I was wrong... Is it possible that you can control the weather with Luminatics?",
  ui_story_32110601_85_dialog_content = "Caelestites can't use Lumina.",
  ui_story_32110601_86_dialog_content = "If you thought the rain was fun, walking on the beach is gonna blow your mind! You haven't tried it yet, have you?",
  ui_story_32110601_87_dialog_content = "I haven't...",
  ui_story_32110601_88_dialog_content = "Well, in that case, let's go.",
  ui_story_32110601_89_option_content = "Take Zarya's hand",
  ui_story_32110601_90_dialog_content = "The sea breeze blowing through the clear blue sky after the rain is so gentle...",
  ui_story_32110601_91_dialog_content = "The sound of my shoes scraping along the beach... I like this sound.",
  ui_story_32110601_92_dialog_content = "Did my sister and the others also experience this very same scene?",
  ui_story_32110601_93_dialog_content = "A hundred years have passed since we made that promise.",
  ui_story_32110601_94_dialog_content = "Is it possible that they had come here to this beach before?",
  ui_story_32110601_95_option_content = "Yes, very likely.",
  ui_story_32110601_96_dialog_content = "I believe they must've come to this beach.",
  ui_story_32110601_97_dialog_content = "They must've experienced the gentle sea breeze after the rain too, and breathed in this fresh ocean air.",
  ui_story_32110601_98_dialog_content = "They probably visited a lot of other places too.",
  ui_story_32110601_99_dialog_content = "Walk in their footsteps and witness the outside world they once explored.",
  ui_story_32110601_100_dialog_content = "Besides, you're pretty fond of the outside world too.",
  ui_story_32110601_101_dialog_content = "Yes, I do like it.",
  ui_story_32110601_102_option_content = "They might not have been here before.",
  ui_story_32110601_103_dialog_content = "They never came here...?",
  ui_story_32110601_104_dialog_content = "But it's precisely because they didn't come here that you need to experience the outside world in their place.",
  ui_story_32110601_105_dialog_content = "You've seen what they were interested in and achieved the kind of life they wanted. That brings your hearts closer together.",
  ui_story_32110601_106_dialog_content = "Besides, you really like this place too.",
  ui_story_32110601_107_dialog_content = "Yes, I do like it.",
  ui_story_32110601_108_dialog_content = "No matter if Alina and Father were here or not, I'll persist on my path nevertheless.",
  ui_story_32110601_109_dialog_content = "I'll go back to Northland with you after experiencing more of what the outside world has to offer, and share all that I have seen and heard with everyone.",
  ui_story_32110601_110_dialog_content = "Moving forward into an unknown world... That's probably why Alina made that promise to you.",
  ui_story_32110601_111_dialog_content = "Remember the past, cherish the present, and look forward to the future. That's all you need to do.",
  ui_story_32110601_112_dialog_content = "Speaking of which, I feel you're forgetting something incredibly important.",
  ui_story_32110601_113_dialog_content = "Huh? Me?",
  ui_story_32110601_114_dialog_content = "Don't you have anything to say about my new outfit?",
  ui_story_32110601_115_dialog_content = "Oh...",
  ui_story_32110601_116_dialog_content = "W-Well... you look good whatever you wear, so I didn't think I needed to say anything, haha...",
  ui_story_32110601_117_dialog_content = "Don't think you can pull the wool over my eyes.",
  ui_story_32110601_118_dialog_content = "But thank you, for accompanying me here.",
  ui_story_32110601_119_dialog_content = "And for taking the time to listen to me talk about the past.",
  ui_story_32110601_120_dialog_content = "I'll continue traveling the world and witnessing more beautiful, unknown places.",
  ui_story_32110601_121_dialog_content = "I promise—I'll never let you or my sister down."
}
return config
